INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(287234, 20065, 1031, '<td valign="top">Your warning comes too late for some of us...</td>', 'Your warning comes too late for some of us...', '2003-05-04 20:37:10.000000', NULL, 1),
(287236, 19900, 1031, '<td valign="top">Good job describing site...like the 3 colors for the ribbons. I''d probably have started the tagline with "Free" (most effective word in advertising) and broken it into two lines with "Digital Photographers" below the rest...you have enough room it would still be uncluttered enough.</td>', 'Good job describing site...like the 3 colors for the ribbons. I''d probably have started the tagline with "Free" (most effective word in advertising) and broken it into two lines with "Digital Photographers" below the rest...you have enough room it would still be uncluttered enough.', '2003-05-04 20:42:35.000000', NULL, 1),
(287237, 20114, 1031, '<td valign="top">We have to find a digital equivalent to the filmstrip motif...</td>', 'We have to find a digital equivalent to the filmstrip motif...', '2003-05-04 20:45:39.000000', NULL, 1),
(287239, 19352, 1031, '<td valign="top">Nice 2-for1 entry -- I think I like the upper one a bit better.</td>', 'Nice 2-for1 entry -- I think I like the upper one a bit better.', '2003-05-04 20:47:14.000000', NULL, 1),
(287241, 20141, 1031, '<td valign="top">Colorful and descriptive. I thinkI''d rather see some photos than the clip art though...</td>', 'Colorful and descriptive. I thinkI''d rather see some photos than the clip art though...', '2003-05-04 20:48:46.000000', NULL, 1),
(287242, 19604, 1031, '<td valign="top">An ad within an ad...</td>', 'An ad within an ad...', '2003-05-04 20:49:20.000000', NULL, 1),
(287246, 20115, 1031, '<td valign="top">Film motif doesn''t make sense, since its use is prohibited. A camera (even a film one -- who can tell?) would have worked better. Maybe a film can with the international red circle-slash ("Not") symbol would work though...</td>', 'Film motif doesn''t make sense, since its use is prohibited. A camera (even a film one -- who can tell?) would have worked better. Maybe a film can with the international red circle-slash ("Not") symbol would work though...', '2003-05-04 20:51:54.000000', NULL, 1),
(287249, 19578, 1031, '<td valign="top">Seems to have some resolution of compression issues, especially with the type. Kind of hard to read the URL.</td>', 'Seems to have some resolution of compression issues, especially with the type. Kind of hard to read the URL.', '2003-05-04 20:54:28.000000', NULL, 1),
(287254, 20152, 1031, '<td valign="top">Provocative tagline, but I think enough additional info should be included to make it clear that it is a photography site.</td>', 'Provocative tagline, but I think enough additional info should be included to make it clear that it is a photography site.', '2003-05-04 20:56:14.000000', NULL, 1),
(287256, 19938, 1031, '<td valign="top">Nice ribbon!</td>', 'Nice ribbon!', '2003-05-04 20:56:52.000000', NULL, 1),
(287259, 19689, 1031, '<td valign="top">I like the flag idea, but maybe should have included tiny versions of all the member nations...</td>', 'I like the flag idea, but maybe should have included tiny versions of all the member nations...', '2003-05-04 20:59:01.000000', NULL, 1),
(287263, 19869, 1031, '<td valign="top">Good idea. I''d move the last line more to the left so it doesn''t overlap the ribbon and has the same indent as the line above. I''d move up mothe the ribbon and the URL to make sure they fit in the printing process.</td>', 'Good idea. I''d move the last line more to the left so it doesn''t overlap the ribbon and has the same indent as the line above. I''d move up mothe the ribbon and the URL to make sure they fit in the printing process.', '2003-05-04 21:02:53.000000', NULL, 1),
(287317, 19797, 6975, '<td valign="top">Simple and to the point.  Easy to look at with the run of blue colors.  The 3D effect of the lettering and symbol makes it very outstanding.</td>', 'Simple and to the point.  Easy to look at with the run of blue colors.  The 3D effect of the lettering and symbol makes it very outstanding.', '2003-05-04 22:54:23.000000', NULL, 1),
(287319, 19465, 6975, '<td valign="top">Would like to see a brighter background color, but the design is excellent.</td>', 'Would like to see a brighter background color, but the design is excellent.', '2003-05-04 22:57:11.000000', NULL, 1),
(287320, 19920, 3532, '<td valign="top">I would like this a lot better if you had done all the text in the same font as the "dpchallenge"  And the dotted lines seem a bit distracting</td>', 'I would like this a lot better if you had done all the text in the same font as the "dpchallenge"  And the dotted lines seem a bit distracting', '2003-05-04 22:58:19.000000', NULL, 1),
(287321, 20076, 6975, '<td valign="top">Interesting!</td>', 'Interesting!', '2003-05-04 22:58:39.000000', NULL, 1),
(287324, 19567, 3532, '<td valign="top">I like the idea, and I really like the light refraction circles, but the half-tone camera doesn''t work for me.  It''s a little hard to figure out what it''s supposed to be and all the dots are just a bit too busy/cluttered.</td>', 'I like the idea, and I really like the light refraction circles, but the half-tone camera doesn''t work for me.  It''s a little hard to figure out what it''s supposed to be and all the dots are just a bit too busy/cluttered.', '2003-05-04 23:02:00.000000', NULL, 1),
(287325, 19724, 6975, '<td valign="top">Could use a bit more imagination?</td>', 'Could use a bit more imagination?', '2003-05-04 23:03:38.000000', NULL, 1),
