(287699, 19938, 5728, '<td valign="top">One of my favourites of the competition. It''s simple, not too much to clutter it up, just perfect - 10.</td>', 'One of my favourites of the competition. It''s simple, not too much to clutter it up, just perfect - 10.', '2003-05-05 08:16:54.000000', NULL, 1),
(287700, 19955, 5728, '<td valign="top">This is fantastic, you sure put a lot of work into this. And it has paid off - 10.</td>', 'This is fantastic, you sure put a lot of work into this. And it has paid off - 10.', '2003-05-05 08:17:37.000000', NULL, 1),
(287702, 19372, 5728, '<td valign="top">Simple and well created, this is a winner! - 10.</td>', 'Simple and well created, this is a winner! - 10.', '2003-05-05 08:18:27.000000', NULL, 1),
